using System.Text;
using Guacamole.SourceGenerators.Models;

namespace Guacamole.SourceGenerators;

/// <summary>
/// Emits the generated partial class for a computing context from its equatable model.
/// Every type reference is fully qualified with <c>global::</c> because the generated file has no usings.
/// </summary>
internal static class ContextEmitter
{
    public static string Emit(ContextModel model)
    {
        var writer = new CodeWriter();
        writer.Line("// <auto-generated/>");
        writer.Line("// Generated by Guacamole Source Generator");
        writer.Line("// This file contains push-based reactive source properties");
        writer.Line("#nullable enable");
        writer.Line();

        if (model.Namespace is not null)
        {
            writer.Line($"namespace {model.Namespace}");
            writer.Open();
        }

        foreach (var containingType in model.ContainingTypes)
        {
            writer.Line($"partial {containingType.Keyword} {containingType.NameWithTypeParameters}");
            writer.Open();
        }

        writer.Line($"partial class {model.ClassName}{model.TypeParameterList}");
        writer.Open();

        WriteBody(writer, model);

        writer.Close();
        foreach (var _ in model.ContainingTypes)
        {
            writer.Close();
        }

        if (model.Namespace is not null)
        {
            writer.Close();
        }

        return writer.ToString();
    }

    private static void WriteBody(CodeWriter writer, ContextModel model)
    {
        // Source fields (push-based reactive sources)
        foreach (var property in model.Properties)
        {
            writer.Line($"private {SourceType(property)}? {FieldName(property)};");
        }

        if (model.Properties.Count > 0)
            writer.Line();

        // Constructor (omitted when the user declared a parameterless constructor, see GUAC0008)
        if (model.GenerateConstructor)
            WriteConstructor(writer, model);

        foreach (var property in model.Properties)
        {
            WriteProviderProperty(writer, property);
            WriteSourceAccessor(writer, property);
        }
    }

    private static void WriteConstructor(CodeWriter writer, ContextModel model)
    {
        writer.Line("/// <summary>");
        writer.Line("/// Initializes the computing context and its sources.");
        writer.Line("/// </summary>");
        writer.Line($"public {model.ClassName}() : base()");
        writer.Open();
        foreach (var property in model.Properties)
        {
            var factory = property.IsCollection ? "CreateSource" : "CreateValueSource";
            writer.Line($"{FieldName(property)} = {factory}<{property.ItemType}>(\"{model.ClassName}.{property.Name}\");");
        }

        writer.Close();
    }

    private static void WriteProviderProperty(CodeWriter writer, SourcePropertyModel property)
    {
        var providerType = property.IsCollection
            ? $"global::Guacamole.IncrementalValuesProvider<{property.ItemType}>"
            : $"global::Guacamole.IncrementalValueProvider<{property.ItemType}>";

        writer.Line();
        writer.Line("/// <summary>");
        writer.Line($"/// Provider for {property.Name}.");
        writer.Line(property.IsCollection
            ? "/// Backed by a push-based incremental source."
            : "/// Backed by a push-based incremental value source.");
        writer.Line("/// </summary>");
        writer.Line($"{Modifiers(property.Accessibility)}partial {providerType} {property.Name}");
        writer.Open();
        writer.Line("get");
        writer.Open();
        WriteNullGuard(writer, property);
        writer.Line();
        writer.Line($"return {FieldName(property)}.AsProvider();");
        writer.Close();
        writer.Close();
    }

    private static void WriteSourceAccessor(CodeWriter writer, SourcePropertyModel property)
    {
        var accessorType = SourceType(property);

        writer.Line();
        writer.Line("/// <summary>");
        writer.Line($"/// Source accessor for {property.Name}.");
        writer.Line(property.IsCollection
            ? "/// Use this to push data into the incremental compilation pipeline."
            : "/// Use this to set the value in the incremental compilation pipeline.");
        writer.Line("/// </summary>");
        writer.Line($"{Modifiers(property.Accessibility)}{accessorType} {property.Name}Source");
        writer.Open();
        writer.Line("get");
        writer.Open();
        WriteNullGuard(writer, property);
        writer.Line();
        writer.Line($"return {FieldName(property)};");
        writer.Close();
        writer.Close();
    }

    private static void WriteNullGuard(CodeWriter writer, SourcePropertyModel property)
    {
        writer.Line($"if ({FieldName(property)} == null)");
        writer.Line($"    throw new global::System.InvalidOperationException(\"Property {property.Name} has not been initialized. This is a framework bug.\");");
    }

    private static string Modifiers(string accessibility) => accessibility.Length == 0 ? string.Empty : accessibility + " ";

    private static string FieldName(SourcePropertyModel property) => $"_{property.Name}Source";

    private static string SourceType(SourcePropertyModel property) => property.IsCollection
        ? $"global::Guacamole.IIncrementalSource<{property.ItemType}>"
        : $"global::Guacamole.IIncrementalValueSource<{property.ItemType}>";

    /// <summary>
    /// Minimal indented writer that always uses '\n' line endings so output is platform independent.
    /// </summary>
    private sealed class CodeWriter
    {
        private readonly StringBuilder _builder = new();
        private int _indent;

        public void Line(string text = "")
        {
            if (text.Length > 0)
                _builder.Append(' ', _indent * 4).Append(text);

            _builder.Append('\n');
        }

        public void Open()
        {
            Line("{");
            _indent++;
        }

        public void Close()
        {
            _indent--;
            Line("}");
        }

        public override string ToString() => _builder.ToString();
    }
}
